```jsx
import React, { useState } from 'react';
import { View, TextInput, Text, TouchableOpacity } from 'react-native';

const Chips = () => {
  const [inputValue, setInputValue] = useState('');
  const [selectedChips, setSelectedChips] = useState([]); // store the selected chips

  const chips = [
    { id: 1, text: 'Chip 1' },
    { id: 2, text: 'Chip 2' },
    { id: 3, text: 'Chip 3' },
  ];

  const handleChipPress = (chip) => {
    // Check if the chip is already selected
    if (selectedChips.includes(chip.id)) {
      // Remove the chip from the selected chips array
      setSelectedChips(selectedChips.filter((cid) => cid !== chip.id));
    } else {
      // Add the chip to the selected chips array
      setSelectedChips([...selectedChips, chip.id]);
    }

    // Update the input value with the selected chip text
    setInputValue((prevInputValue) => {
      if (selectedChips.length > 0) {
        return selectedChips.map((cid) => chips.find((chip) => chip.id === cid).text).join(', ');
      }
      return prevInputValue;
    });
  };

  return (
    <View>
      <TextInput
        value={inputValue}
        onChangeText={(text) => setInputValue(text)}
        placeholder="Type something..."
        style={{ borderColor: 'gray', borderWidth: 1, padding: 10 }}
      />
      {chips.map((chip) => (
        <TouchableOpacity key={chip.id} onPress={() => handleChipPress(chip)}>
          <Text style={{ fontSize: 16, padding: 10 }}>{chip.text}</Text>
        </TouchableOpacity>
      ))}
    </View>
  );
};

export default Chips;
```
